const raw = $input.first().json.response || '';
let structure = {};
try {
    const match = raw.match(/\{([\s\S]*?)\}(?=[^}]*$)/);
    structure = JSON.parse('{' + match[1] + '}');
} catch(e) {
    structure = {title:'Dubai Market 2027',title_en:'dubai-market-2027',meta_description:'Dubai Business Guide',h1:'Dubai Guide',h2_sections:['Intro','Opportunities','Tools','Summary'],cta_text:'Free Consult',cta_link:'/#lead-magnet',lsi_keywords:['Dubai','Business','Iran'],word_count_target:1800};
}
const incoming = $node['Webhook'].json.body;
return [{ json: { ...structure, original_keyword: incoming.keyword, funnel_stage: incoming.funnel_stage, related_expo: incoming.related_expo } }];
}
